<?php require 'config.php';$q=trim($_GET['q']??'');$rows=[];if($q){$s=db()->prepare("SELECT * FROM tickets WHERE ticket_no=? OR email=? ORDER BY created_at DESC");$s->execute([$q,$q]);$rows=$s->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My requests — DeskFlow</title><link rel="stylesheet" href="assets/style.css"></head><body><nav class="top"><a class="logo" href="index.php"><span>desk</span>flow</a><div class="links"><a href="index.php">Help center</a><a href="articles.php">Articles</a><a class="active" href="track.php">My requests</a><a class="outline" href="request.php">Contact support</a><a class="admin" href="admin/login.php">Admin</a></div></nav><main class="requests"><div class="requesthero"><small>REQUESTS</small><h1>Track your support.</h1><p>Enter your ticket number or the email you used when contacting us.</p><form><input name="q" value="<?=e($q)?>" placeholder="Ticket number or email"><button>Find requests</button></form></div><?php if($q&&!$rows):?><div class="noresults">We couldn't find any requests for that search.</div><?php endif;?><?php foreach($rows as $r):?><article class="ticketrow"><div><small><?=e($r['ticket_no'])?></small><h2><?=e($r['subject'])?></h2><p><?=e($r['category'])?> · <?=e(date('M j, Y',strtotime($r['created_at'])))?></p></div><span class="ticketstatus <?=e($r['status'])?>"><?=e($r['status'])?></span><div class="ticketmessage"><?=nl2br(e($r['message']))?><?php if($r['agent_reply']):?><div class="agentreply"><b>Support reply</b><br><?=nl2br(e($r['agent_reply']))?></div><?php endif;?></div></article><?php endforeach;?></main></body></html>